import json,os,selectors,sqlite3,subprocess,sys,tempfile,hashlib
from pathlib import Path
from contextlib import closing
from src import adapter
scratch=Path(__file__).resolve().parent
B=[('old',2),('same',1)]; N=[('new',3),('old',2),('same',7)]
def observe(path):
 with closing(sqlite3.connect(path)) as db:
  return {'rows':db.execute('SELECT * FROM inventory ORDER BY sku').fetchall(),'aux':db.execute('SELECT * FROM auxiliary').fetchall(),'integrity':db.execute('PRAGMA integrity_check').fetchone()[0]}
def one(journal,stop):
 with tempfile.TemporaryDirectory(dir=scratch,prefix='tx-') as temp:
  dest=Path(temp)/'visible.sqlite'; stage=Path(temp)/'stage.sqlite'
  adapter.apply(str(dest),[{'sku':s,'quantity':q} for s,q in B])
  with closing(sqlite3.connect(dest)) as db:
   got=db.execute('PRAGMA journal_mode='+journal).fetchone()[0]
   db.execute('CREATE TABLE auxiliary (marker TEXT)'); db.execute("INSERT INTO auxiliary VALUES ('preserved')"); db.commit()
  stage_result=adapter.apply(str(stage),[{'sku':'same','quantity':7},{'sku':'new','quantity':3}])
  argv=[sys.executable,'-B',str(scratch/'tx_child.py'),str(dest),str(stage),'raise' if stop=='raise' else 'normal']
  reader=None
  if stop=='commit-blocked':
   reader=sqlite3.connect(dest,isolation_level=None); reader.execute('BEGIN'); reader.execute('SELECT * FROM inventory').fetchall()
  p=subprocess.Popen(argv,stdin=subprocess.PIPE,stdout=subprocess.PIPE,stderr=subprocess.PIPE,text=True,bufsize=1)
  seen=[]
  def nextline():
   data=b''
   with selectors.DefaultSelector() as sel:
    sel.register(p.stdout,selectors.EVENT_READ)
    while not data.endswith(b'\n'):
     if not sel.select(5): raise RuntimeError('barrier timeout')
     ch=os.read(p.stdout.fileno(),1)
     if not ch: raise RuntimeError('child EOF before barrier')
     data+=ch
   line=data.decode().strip(); seen.append(line); return line
  def go(): p.stdin.write('continue\n'); p.stdin.flush()
  try:
   assert nextline()=='mid-write'
   if stop!='mid':
    go()
    if stop=='raise': pass
    else:
     assert nextline()=='pre-commit'
     if stop not in ('pre','commit-blocked'):
      go(); assert nextline()=='commit-start'; assert nextline()=='post-commit'
      if stop in ('success','repeat'): go()
     elif stop=='commit-blocked':
      go(); assert nextline()=='commit-start'
   if stop not in ('success','repeat','raise'): p.kill()
   out,err=p.communicate(timeout=5)
  finally:
   if p.poll() is None: p.kill(); p.communicate(timeout=5)
   if reader: reader.close()
  first=observe(dest); again=observe(dest)
  expected=N if stop in ('post','success','repeat') else B
  assert first['rows']==expected and again==first and first['aux']==[('preserved',)] and first['integrity']=='ok', (stop,first)
  if stop in ('success','repeat'): assert p.returncode==0 and 'acknowledged' in out
  elif stop=='raise': assert p.returncode!=0 and 'injected publication error' in err
  else: assert p.returncode==-9
  # Repeat a committed batch through the same publication primitive, not a product function.
  repeat=None
  if stop=='repeat':
   with closing(sqlite3.connect(dest,isolation_level=None)) as db:
    db.execute('BEGIN IMMEDIATE')
    for row in [('same',7),('new',3)]: db.execute('INSERT INTO inventory VALUES (?,?) ON CONFLICT(sku) DO UPDATE SET quantity=excluded.quantity',row)
    db.commit()
   repeat=observe(dest); assert repeat['rows']==N
  return {'journal_requested':journal,'journal_observed':got,'stop':stop,'argv':argv,'barriers':seen,'exit_code':p.returncode,'stdout_tail':out,'stderr':err,'stage_result':stage_result,'fresh_observation':first,'second_reopen':again,'repeat':repeat}
rows=[]
for journal in ['DELETE','WAL']:
 for stop in ['mid','pre','post','raise','repeat']:
  rows.append(one(journal,stop))
rows.append(one('DELETE','commit-blocked'))
